System.register("chunks:///_virtual/manifest.ts",["cc"],(function(e){var a;return{setters:[function(e){a=e.cclegacy}],execute:function(){a._RF.push({},"5ac9cgWPY1LDKu1hxzoSa30","manifest",void 0);e("MANIFEST",{manifest_version:1,game_id:"sg-2048",slug:"2048",name:{en:"2048",it:"2048"},description:{en:"Swipe, merge equal tiles and build 2048. One more move, always.",it:"Scorri, unisci le tessere uguali e arriva a 2048. Sempre una mossa in più."},genre:"puzzle",template_id:"merge",engine:"cocos-3.8.8",version:"1.0.0",orientation:"portrait",game_rules:{variant:"merge_2048",start_tiles:2,four_percent:10,target_tile:2048,max_moves:2e4,modes:[{id:"classic",size:4},{id:"big",size:5}]},scoring_rules:{points:"merged_value"},supported_platforms:["web","telegram"],supported_locales:["en","it"],default_locale:"en",target_countries:["*"],age_rating:"PEGI 3",privacy_profile:{personal_data:!1,analytics:"pseudonymous_install",account_required:!1},monetization_profile:{rewarded_ads:!1,interstitial_ads:!1,iap:!0},social_profile:{share:!0,leaderboard:!0,challenge:!0},analytics_profile:{sink:"memory",flush_interval_ms:5e3},difficulty_config:{level:"normal"},asset_manifest:{theme:"settegames",palette:{background:"#FFC83D",primary:"#3B82FF",accent:"#FF2D8B",text:"#1A0B4B",muted:"#F4F6FF"},sounds:"synth",provenance:"Colori dal brand kit SetteGames (giallo #FFC83D come campo, blu, rosa, viola-scuro, bianco-lavanda); caratteri Titan One e Baloo 2 (OFL, da Scopa, come Perfect Timer); suoni sintetizzati dal codice; tessere, griglia e icone disegnate dal codice. Nessun asset di terzi. Direzione: .impeccable.md"},build_config:{targets:["web-mobile"],max_gzip_kb:1200},release_config:{channels:["web","telegram"],status:"draft"},legal_status:{original_concept:!1,trademark_check:"pending",gambling_mechanics:!1,notes:'"2048" è il nome generico di un genere di puzzle a scorrimento (originale di Gabriele Cirulli, 2014, rilasciato con licenza MIT, a sua volta ispirato a Threes!/1024). Il gioco usa il nome come descrizione del genere: nessun codice, grafica, logo, font, colori o testo presi dall\'originale né da Threes!. Regole reimplementate da zero (templates/merge/logic), grafica disegnata dal codice, palette del brand SetteGames. Nessun marchio di terzi nelle parole chiave SEO. Da confermare il controllo marchi prima della pubblicazione.'},experiment_config:{active:[]},seo:{keywords:["2048","play 2048 online","2048 game","2048 puzzle","free 2048","2048 5x5","number merge puzzle","sliding tile puzzle"],headline:{en:"Play 2048 online",it:"Gioca a 2048 online"},long_description:{en:"2048 is the sliding number puzzle you can play for free in your browser or on Telegram, with no download and no sign-up. Swipe to move every tile at once, merge equal numbers and try to build the 2048 tile. Choose the classic 4×4 board or the roomier 5×5 board for longer runs, then challenge a friend to beat your score on the weekly leaderboard.",it:"2048 è il puzzle numerico a scorrimento che puoi giocare gratis nel browser o su Telegram, senza scaricare nulla e senza registrarti. Scorri per spostare tutte le tessere insieme, unisci i numeri uguali e prova a costruire la tessera 2048. Scegli la griglia classica 4×4 o quella più ampia 5×5 per partite più lunghe, poi sfida un amico a battere il tuo punteggio nella classifica della settimana."},how_to_play:{en:["Swipe up, down, left or right (or use the arrow keys or WASD) to slide every tile on the board.","When two tiles with the same number touch, they merge into one tile with double the value.","Every merge adds the new tile's value to your score.","After each move a new 2 (sometimes a 4) appears in an empty cell.","Reach the 2048 tile to win, then keep going for a higher score. The game ends when no move is left."],it:["Scorri in su, in giù, a sinistra o a destra (o usa le frecce o WASD) per far scivolare tutte le tessere.","Quando due tessere con lo stesso numero si toccano, diventano una sola tessera di valore doppio.","Ogni unione aggiunge al punteggio il valore della nuova tessera.","Dopo ogni mossa compare un 2 (a volte un 4) in una cella vuota.","Arriva alla tessera 2048 per vincere, poi continua per fare più punti. La partita finisce quando non ci sono più mosse."]},faq:[{q:{en:"Is 2048 free to play?",it:"2048 è gratis?"},a:{en:"Yes. You play the full game for free in your browser or on Telegram, with no download and no account. Optional color themes are cosmetic only and never change the game.",it:"Sì. Il gioco completo è gratis nel browser o su Telegram, senza download e senza account. I temi colore facoltativi sono solo estetici e non cambiano mai il gioco."}},{q:{en:"What is the best strategy for 2048?",it:"Qual è la strategia migliore per 2048?"},a:{en:"Pick a corner and keep your biggest tile there. Mostly use two directions (for example down and left), add the third only when needed and avoid the fourth, so the large tiles stay lined up along one edge and merge in a chain.",it:"Scegli un angolo e tieni lì la tessera più grande. Usa soprattutto due direzioni (per esempio giù e sinistra), la terza solo quando serve ed evita la quarta: così le tessere grandi restano in fila lungo un bordo e si uniscono a catena."}},{q:{en:"Can I keep playing after reaching 2048?",it:"Posso continuare dopo aver fatto 2048?"},a:{en:"Yes. When you build the 2048 tile you get a celebration, then you can keep going for 4096 and beyond to push your score higher.",it:"Sì. Quando costruisci la tessera 2048 c'è una festa, poi puoi continuare verso 4096 e oltre per alzare il punteggio."}},{q:{en:"What is the difference between 4×4 and 5×5?",it:"Che differenza c'è fra 4×4 e 5×5?"},a:{en:"The classic 4×4 board is the tight, tense version. The 5×5 board has more room, so games last longer and bigger tiles are within reach. Each board has its own best score and leaderboard.",it:"La griglia classica 4×4 è la versione stretta e tesa. La 5×5 ha più spazio: le partite durano di più e le tessere grandi sono più vicine. Ogni griglia ha il suo record e la sua classifica."}},{q:{en:"Is there an undo button?",it:"Si può annullare una mossa?"},a:{en:"No. Every move counts, which keeps the weekly leaderboard fair for everyone. Scores are checked by replaying your moves on our server.",it:"No. Ogni mossa conta, così la classifica settimanale resta giusta per tutti. I punteggi vengono verificati rigiocando le tue mosse sul nostro server."}},{q:{en:"Who made the original 2048?",it:"Chi ha inventato 2048?"},a:{en:"2048 was created by Gabriele Cirulli in 2014 and released as open source. This version is a new implementation by SetteGames with its own code and graphics.",it:"2048 è stato creato da Gabriele Cirulli nel 2014 e pubblicato come open source. Questa versione è una nuova realizzazione di SetteGames, con codice e grafica propri."}}]}}),e("BUILD_INFO",{hash:"9faf96b618579628",hubUrl:"https://jvmpwhoosojharlbmgsi.supabase.co/functions/v1/hub-api"});a._RF.pop()}}}));

